const FRAME_WIDTH = 376;
const FRAME_HEIGHT = 240;
const HBLANK_WIDTH = 80;
const VBLANK_HEIGHT = 22;

const CONTENT_WIDTH = 320;
const CONTENT_HEIGHT = 200;

const BORDER_WIDTH = (FRAME_WIDTH - CONTENT_WIDTH) / 2;
const BORDER_HEIGHT = (FRAME_HEIGHT - CONTENT_HEIGHT) / 2;

const CONTENT_TOP = VBLANK_HEIGHT + BORDER_HEIGHT;
const CONTENT_LEFT = HBLANK_WIDTH + BORDER_WIDTH;

const REG_ISR = 0x00;
const REG_IMR = 0x01;
const REG_FLAGS = 0x02;
const REG_OFFSETS = 0x03;
const REG_BGCOL = 0x04;
const REG_RASTERLINE = 0x05;
const REG_SERIAL_RDY = 0x06;
const REG_SERIAL_DATA = 0x07;
const SCROLL_X_HIGH = 0x08;
const SCROLL_X_LOW = 0x09;
const SCROLL_Y = 0x0a;
const REG_CURSOR_X = 0x0b;
const REG_CURSOR_Y = 0x0c;
const REG_PALETTE = 0x10;
const REG_SPRITES_FLAGS = 0x30;
const REG_SPRITES_X = 0x50;
const REG_SPRITES_Y = 0x70;
const REG_SPRITES_TILE = 0x90;

const CHAR_COLUMNS = 40;
const CHAR_ROWS = 25;
const CHAR_DELAY = 16;
const SCROLL_DELAY = 1024 * 48;
const BLINK_SPEED = 48;

export class VDP {
  public framebuffer: Uint8Array;

  private hpos = 0;
  private vpos = 0;
  private registers: Uint8Array = new Uint8Array(256);
  private tileCache: Uint8Array = new Uint8Array(41);
  private tileFlagCache: Uint8Array = new Uint8Array(41);
  private tileGraphicsCache1: Uint8Array = new Uint8Array(41);
  private tileGraphicsCache2: Uint8Array = new Uint8Array(41);

  private activeSpritesBuffer: Uint8Array = new Uint8Array(16);
  private spritePixelBufferL: Uint8Array = new Uint8Array(16);
  private spritePixelBufferR: Uint8Array = new Uint8Array(16);

  private inVBorder = true;
  private inHBorder = true;
  private bitmapByte: Uint8Array = new Uint8Array(1);

  private serialBuffer: Uint8Array;
  private cursorBlink: number = 0;
  private charCooldown: number = 0;
  private scrollCooldown: number = 0;

  public scrollLock = false;

  public isStealingCycles = false;

  constructor() {
    this.framebuffer = new Uint8Array(FRAME_WIDTH * FRAME_HEIGHT * 4);
    this.serialBuffer = new Uint8Array(CHAR_COLUMNS * CHAR_ROWS).fill(0x20);
    this.registers[REG_PALETTE + 1] = 0x0f;
    this.registers[REG_PALETTE + 16 + 1] = 0x0f;
  }

  readReg(addr: number): number {
    switch (addr) {
      case REG_SERIAL_RDY: // serial ready
        return this.charCooldown + this.scrollCooldown > 0 ? 0x00 : 0x80;
      case REG_RASTERLINE:
        return this.vpos - 22;
      default:
        return this.registers[addr] ?? 0;
    }
  }
  writeReg(addr: number, val: number): void {
    switch (addr) {
      case REG_CURSOR_X:
        this.registers[addr] = Math.min(val, CHAR_COLUMNS - 1);
        break;
      case REG_CURSOR_Y:
        this.registers[addr] = Math.min(val, CHAR_ROWS - 1);
        break;
      case REG_SERIAL_DATA: // serial data
        this.serialIn(val);
        break;
      default:
        this.registers[addr] = val;
    }
  }

  serialIn(c: number) {
    if (c === 10) {
      // newline
      this.registers[REG_CURSOR_X] = 0;
      this.registers[REG_CURSOR_Y] += 1;
      // this.cursorPos =
      // 	(Math.floor(this.cursorPos / CHAR_COLUMNS) + 1) * CHAR_COLUMNS;
    } else if (c == 8) {
      // backspace
      if (
        this.registers[REG_CURSOR_X] == 0 &&
        this.registers[REG_CURSOR_Y] != 0
      ) {
        this.registers[REG_CURSOR_Y] -= 1;
        this.registers[REG_CURSOR_X] = CHAR_COLUMNS - 1;
      } else if (this.registers[REG_CURSOR_X] != 0) {
        this.registers[REG_CURSOR_X] -= 1;
      }
      // if (this.cursorPos > 0) {
      // 	this.cursorPos--;
      // }
    } else if (c == 0x0d) {
      // carriage return
      this.registers[REG_CURSOR_X] = 0;
    } else if (c == 0x0c) {
      // form feed
      this.registers[REG_CURSOR_X] = 0;
      this.registers[REG_CURSOR_Y] = 0;

      this.serialBuffer.fill(0x20);
      this.scrollCooldown = SCROLL_DELAY;
    } else {
      // normal characters
      this.serialBuffer[
        this.registers[REG_CURSOR_Y] * CHAR_COLUMNS +
          this.registers[REG_CURSOR_X]
      ] = c;
      this.registers[REG_CURSOR_X] += 1;
    }

    if (this.registers[REG_CURSOR_X] >= CHAR_COLUMNS) {
      this.registers[REG_CURSOR_X] = 0;
      this.registers[REG_CURSOR_Y] += 1;
    }

    if (this.registers[REG_CURSOR_Y] >= CHAR_ROWS) {
      // scroll down
      for (var i = 0; i < CHAR_COLUMNS * (CHAR_ROWS - 1); i++) {
        this.serialBuffer[i] = this.serialBuffer[i + CHAR_COLUMNS];
      }
      for (
        var i = CHAR_COLUMNS * (CHAR_ROWS - 1);
        i < CHAR_COLUMNS * CHAR_ROWS;
        i++
      ) {
        this.serialBuffer[i] = 0x20;
      }
      this.registers[REG_CURSOR_Y] -= 1;
      this.scrollCooldown = SCROLL_DELAY;
    }
    this.charCooldown = CHAR_DELAY;
  }

  mode012(exnil: Exnil80) {
    let col = 0;
    const mode = this.registers[REG_FLAGS] & 0b111;
    let scrollX =
      ((this.registers[SCROLL_X_HIGH] & 1) << 8) | this.registers[SCROLL_X_LOW];
    if (mode == 0) scrollX = 0;
    const fineX = scrollX & 0x07;

    let scrollY = this.registers[SCROLL_Y];
    if (mode == 0) scrollY = 0;
    const fineY = scrollY & 0x07;
    const contentX = this.hpos - CONTENT_LEFT;
    const contentY = this.vpos - CONTENT_TOP;
    const vram = (this.registers[REG_OFFSETS] & 0b11) * 0x4000;
    const tilemap =
      vram + ((this.registers[REG_OFFSETS] >>> 2) & 0b11) * 0x1000;
    const internalY = (this.vpos - CONTENT_TOP + fineY) & 0x07;

    const badline =
      (internalY == 0 || this.vpos == CONTENT_TOP) && !this.inHBorder;

    if (
      this.hpos >= CONTENT_LEFT - 16 &&
      this.hpos < CONTENT_LEFT + CONTENT_WIDTH - 8 &&
      badline
    ) {
      //col = 0x07;
      this.isStealingCycles = true;
      const tileX = (this.hpos - (CONTENT_LEFT - 16)) >>> 3;
      const tileY = (this.vpos - CONTENT_TOP + fineY) >>> 3;
      const coarseX = scrollX >> 3;
      const coarseY = scrollY >> 3;
      const fetchX = (tileX + coarseX) & 0x3f;
      const fetchY = (tileY + coarseY) & 0x1f;

      if ((contentX & 0x07) == 2) {
        // tile fetch
        if (mode == 0) {
          this.tileCache[tileX] = this.serialBuffer[fetchX + fetchY * 40];
        } else {
          this.tileCache[tileX] = exnil.memget(
            tilemap + fetchX * 2 + fetchY * 128 + 1
          );
        }
      }
      if ((contentX & 0x07) == 6) {
        // tile flags fetch
        if (mode == 0) {
          this.tileFlagCache[tileX] = 0;
        } else {
          this.tileFlagCache[tileX] = exnil.memget(
            tilemap + fetchX * 2 + fetchY * 128
          );
        }
      }
    }

    if (
      this.hpos >= CONTENT_LEFT - 8 &&
      this.hpos < CONTENT_LEFT + CONTENT_WIDTH - 0
    ) {
      const tileX = (this.hpos - (CONTENT_LEFT - 8)) >>> 3;
      const tile = this.tileCache[tileX];
      const flags = this.tileFlagCache[tileX];
      const bank = flags & 0b11;
      // tile graphics fetch
      if ((contentX & 0x07) == 0) {
        //left half tile graphics
        const flipX = (flags & 0b00100000) > 0;
        const flipY = (flags & 0b00010000) > 0;
        const y = flipY ? 7 - internalY : internalY;
        let g = 0;
        if (mode == 2) {
          g = exnil.memget(
            vram + bank * 0x1000 + tile * 16 + y * 2 + (flipX ? 1 : 0)
          );
        } else {
          g = CHARMAP[tile * 16 + y * 2 + (flipX ? 1 : 0)];
        }
        this.tileGraphicsCache1[tileX] = g;
      }
      if ((contentX & 0x07) == 4) {
        //right half tile graphics
        const flipX = (flags & 0b00100000) > 0;
        const flipY = (flags & 0b00010000) > 0;
        const y = flipY ? 7 - internalY : internalY;
        let g = 0;
        if (mode == 2) {
          g = exnil.memget(
            vram + bank * 0x1000 + tile * 16 + y * 2 + (flipX ? 0 : 1)
          );
        } else {
          g = CHARMAP[tile * 16 + y * 2 + (flipX ? 0 : 1)];
        }

        this.tileGraphicsCache2[tileX] = g;
      }
    }

    const tileX = (contentX + fineX) >>> 3;
    const tileY = (contentY + fineY) >>> 3;
    const internalX = (contentX + fineX) & 0x07;

    const flipX = (this.tileFlagCache[tileX] & 0b00100000) > 0;
    const tile_palette = (this.tileFlagCache[tileX] >> 2) & 0b11;
    let pal_index = 0;
    if (flipX) {
      const pixelWord =
        (this.tileGraphicsCache2[tileX] << 8) | this.tileGraphicsCache1[tileX];
      pal_index = (pixelWord >> (internalX * 2)) & 0x03;
    } else {
      const pixelWord =
        (this.tileGraphicsCache1[tileX] << 8) | this.tileGraphicsCache2[tileX];
      pal_index = (pixelWord >> ((7 - internalX) * 2)) & 0x03;
    }
    if (mode == 0 && (this.registers[REG_FLAGS] & 0b1000) == 0) {
      if (
        this.cursorBlink < BLINK_SPEED / 2 &&
        this.registers[REG_CURSOR_X] == tileX &&
        this.registers[REG_CURSOR_Y] == tileY
      ) {
        pal_index = (pal_index & 0b10) | (~pal_index & 0b01);
      }
    }

    col = this.registers[REG_PALETTE + tile_palette * 4 + pal_index];

    if (mode != 0) {
      for (let i = 0; i < 16; i++) {
        if ((this.activeSpritesBuffer[i] & 0x80) > 0) {
          // sprite is active
          const spriteIndex = this.activeSpritesBuffer[i] & 0x1f;

          const flags = this.registers[REG_SPRITES_FLAGS + spriteIndex];
          let width = 8;
          if ((flags & 0b1000) > 0) width *= 2;
          const x =
            ((flags & 1) << 8) | this.registers[REG_SPRITES_X + spriteIndex];
          const flipX = (flags & 0b10000000) > 0;

          if (this.hpos >= x && this.hpos < x + width) {
            let internalX = this.hpos - x;
            const stretchX = (flags & 0b1000) > 0;
            if (stretchX) internalX = internalX >>> 1;

            let pal_index = 0;
            if (flipX) {
              const pixelWord =
                (this.spritePixelBufferL[i] << 8) | this.spritePixelBufferR[i];
              pal_index = (pixelWord >> (internalX * 2)) & 0x03;
            } else {
              const pixelWord =
                (this.spritePixelBufferL[i] << 8) | this.spritePixelBufferR[i];
              pal_index = (pixelWord >> ((7 - internalX) * 2)) & 0x03;
            }

            const palette = (flags >> 4) & 0b11;

            if (pal_index != 0) {
              col =
                this.registers[REG_PALETTE + 0x10 + palette * 4 + pal_index];
              break;
            }
          }
        } else {
          break;
        }
      }
    }

    return col;
  }

  hblank(exnil: Exnil80) {
    const mode = this.registers[REG_FLAGS] & 0b111;

    if (mode != 2 && mode != 1) return;

    if (this.hpos == 0) {
      this.activeSpritesBuffer = this.activeSpritesBuffer.fill(0);

      let hitSprites = 0;

      // get all the sprites for the upcoming line
      for (let i = 0; i < 32; i++) {
        const flags = this.registers[REG_SPRITES_FLAGS + i];
        let height = 8;
        if ((flags & 0b10) > 0) height *= 2;
        if ((flags & 0b100) > 0) height *= 2;
        const y = this.registers[REG_SPRITES_Y + i];

        if (this.vpos >= y && this.vpos < y + height) {
          this.activeSpritesBuffer[hitSprites] = 0x80 | i;
          hitSprites++;
          if (hitSprites == 16) break;
        }
      }
    }
    if (this.hpos < 16 * 2 * 4) {
      const i = this.hpos >> 4;
      const spriteID = this.activeSpritesBuffer[i] & 0x1f;
      const y = this.registers[REG_SPRITES_Y + spriteID];
      let internalY = this.vpos - y;
      const flags = this.registers[REG_SPRITES_FLAGS + spriteID];
      const flipY = (flags & 0b01000000) > 0;
      const doubleHeight = (flags & 0b10) > 0;
      const stretchY = (flags & 0b100) > 0;
      const spriteBank = ((this.registers[REG_OFFSETS] >>> 4) & 0b11) * 0x1000;

      if (stretchY) internalY = internalY >>> 1;

      if (flipY) {
        internalY = (doubleHeight ? 15 : 7) - internalY;
      }

      const vram = (this.registers[REG_OFFSETS] & 0b11) * 0x4000;
      const tileID = this.registers[REG_SPRITES_TILE + spriteID];
      if ((this.hpos & 0x07) == 0) {
        // sprite pixel data fetch
        this.spritePixelBufferL[i] = exnil.memget(
          vram + spriteBank + tileID * 16 + internalY * 2 + 0
        );
        if (mode == 2) {
          this.spritePixelBufferL[i] = exnil.memget(
            vram + spriteBank + tileID * 16 + internalY * 2 + 0
          );
        } else {
          this.spritePixelBufferL[i] = CHARMAP[tileID * 16 + internalY * 2 + 0];
        }
      }
      if ((this.hpos & 0x07) == 4) {
        // sprite pixel data fetch
        if (mode == 2) {
          this.spritePixelBufferR[i] = exnil.memget(
            vram + spriteBank + tileID * 16 + internalY * 2 + 1
          );
        } else {
          this.spritePixelBufferR[i] = CHARMAP[tileID * 16 + internalY * 2 + 1];
        }
      }
    }
  }

  mode3(exnil: Exnil80) {
    let col = 0;
    const contentX = this.hpos - CONTENT_LEFT;
    const contentY = this.vpos - CONTENT_TOP;
    const vram = (this.registers[REG_OFFSETS] & 0b11) * 0x4000;

    if ((contentX & 0x03) == 0) {
      this.bitmapByte[0] = exnil.memget(
        vram + (contentX >>> 2) + contentY * 80
      );
    }

    let pal_index = (this.bitmapByte[0] >>> 6) & 0b11;
    this.bitmapByte[0] = this.bitmapByte[0] << 2;

    col = this.registers[REG_PALETTE + pal_index];

    return col;
  }

  mode4(exnil: Exnil80) {
    let col = 0;
    const contentX = this.hpos - CONTENT_LEFT;
    const contentY = this.vpos - CONTENT_TOP;
    const vram = (this.registers[REG_OFFSETS] & 0b11) * 0x4000;

    if ((contentX & 0x03) == 0) {
      this.bitmapByte[0] = exnil.memget(
        vram + (contentX >>> 2) + contentY * 80
      );
    }

    let pal_index = (this.bitmapByte[0] >>> 4) & 0b1111;

    if ((contentX & 1) == 1) this.bitmapByte[0] = this.bitmapByte[0] << 4;

    col = this.registers[REG_PALETTE + pal_index];

    return col;
  }

  cycle(exnil: Exnil80) {
    let col = 0;
    this.isStealingCycles = false;

    if (this.charCooldown > 0) {
      this.charCooldown--;
    }

    if (!this.scrollLock && this.scrollCooldown > 0) {
      this.scrollCooldown--;
    }

    if (this.hpos < HBLANK_WIDTH) {
      // hblank
      this.hblank(exnil);
    } else if (this.vpos < VBLANK_HEIGHT) {
      // vblank
    } else {
      if (this.vpos == CONTENT_TOP) this.inHBorder = false;
      if (this.vpos == CONTENT_TOP + CONTENT_HEIGHT) this.inHBorder = true;
      if (this.hpos == CONTENT_LEFT) this.inVBorder = false;
      if (this.hpos == CONTENT_LEFT + CONTENT_WIDTH) this.inVBorder = true;

      const mode = this.registers[REG_FLAGS] & 0b111;

      switch (mode) {
        case 0:
        case 1:
        case 2:
          col = this.mode012(exnil);
          break;
        case 3:
          col = this.mode3(exnil);
          break;
        case 4:
          col = this.mode4(exnil);
          break;
      }

      if (this.inHBorder || this.inVBorder) col = this.registers[REG_BGCOL];

      this.framebuffer[
        (this.hpos - HBLANK_WIDTH) * 4 +
          (this.vpos - VBLANK_HEIGHT) * FRAME_WIDTH * 4 +
          0
      ] = (PALETTE[col ^ 0x08] >> 16) & 0xff;
      this.framebuffer[
        (this.hpos - HBLANK_WIDTH) * 4 +
          (this.vpos - VBLANK_HEIGHT) * FRAME_WIDTH * 4 +
          1
      ] = (PALETTE[col ^ 0x08] >> 8) & 0xff;
      this.framebuffer[
        (this.hpos - HBLANK_WIDTH) * 4 +
          (this.vpos - VBLANK_HEIGHT) * FRAME_WIDTH * 4 +
          2
      ] = (PALETTE[col ^ 0x08] >> 0) & 0xff;
    }

    this.hpos++;

    if (this.hpos == 456) {
      this.vpos++;
      this.hpos = 0;

      if (
        this.vpos - 22 == this.registers[REG_RASTERLINE] &&
        (this.registers[REG_IMR] & 0x40) > 0
      ) {
        this.registers[REG_ISR] |= 0x40;
        exnil.cpu.interrupt();
      }

      if (this.vpos == 262) {
        this.vpos = 0;

        this.cursorBlink = (this.cursorBlink + 1) % BLINK_SPEED;

        // trigger vblank interrupt
        if ((this.registers[REG_IMR] & 0x80) > 0) {
          this.registers[REG_ISR] |= 0x80;
          exnil.cpu.interrupt();
        }
      }
    }
  }
}
